const $=id=>document.getElementById(id);let recorder,stream,chunks=[],blob,previewURL,timer,group,uploading=false,requesting=false,generation=0,ticker,uploadController;
function stopTracks(){stream?.getTracks().forEach(track=>track.stop());stream=null;clearTimeout(timer);clearInterval(ticker)}
function discard(){generation++;uploadController?.abort();uploadController=null;uploading=false;requesting=false;$('voice-record').disabled=false;if(recorder?.state==='recording'){recorder.onstop=null;recorder.stop()}stopTracks();recorder=null;blob=null;if(previewURL)URL.revokeObjectURL(previewURL);previewURL=null;$('voice-preview').removeAttribute('src');$('voice-preview').hidden=true;$('voice-clock').textContent='';$('voice-file').disabled=false;$('voice-attach').disabled=true;$('voice-record').textContent='Record';$('voice-status').textContent='Record up to 60 seconds, or choose an audio file (8 MB maximum).'}
function clipIssue(text){if(!uploading&&recorder?.state!=='recording')$('voice-attach').disabled=!blob;$('voice-status').textContent=text+(blob?' Your previous clip is still ready to attach.':'')}
function preview(value){if(!value.size||value.size>8000000){clipIssue('Clip is empty or exceeds 8 MB.');return}$('voice-preview').pause();$('voice-preview').hidden=true;$('voice-attach').disabled=true;blob=value;if(previewURL)URL.revokeObjectURL(previewURL);previewURL=URL.createObjectURL(blob);$('voice-preview').src=previewURL;$('voice-preview').hidden=false;$('voice-attach').disabled=false;$('voice-status').textContent='Listen to your clip, then attach it. It will not send until you press Send.'}
$('voice-open').onclick=()=>{group=window.DockGroupMeAudioTarget.current();if(!group)return;discard();$('voice-dialog').showModal()};
$('voice-record').onclick=async()=>{if(uploading||requesting)return;if(recorder?.state==='recording'){recorder.stop();return}const version=generation;requesting=true;$('voice-preview').pause();try{if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder)throw Error('Recording is unavailable. Choose an audio file instead.');const acquired=await navigator.mediaDevices.getUserMedia({audio:true});if(version!==generation||!$('voice-dialog').open){acquired.getTracks().forEach(track=>track.stop());return}stream=acquired;const type=['audio/mp4','audio/webm;codecs=opus','audio/ogg;codecs=opus'].find(t=>MediaRecorder.isTypeSupported(t));if(!type)throw Error('This browser cannot record a supported audio format. Choose a file instead.');chunks=[];recorder=new MediaRecorder(stream,{mimeType:type,audioBitsPerSecond:96000});recorder.ondataavailable=e=>{if(version===generation&&e.data.size)chunks.push(e.data)};recorder.onstop=()=>{if(version!==generation)return;stopTracks();$('voice-file').disabled=false;$('voice-record').textContent='Record again';preview(new Blob(chunks,{type:recorder.mimeType}))};recorder.onerror=()=>{if(version!==generation)return;stopTracks();$('voice-status').textContent='Recording failed. Try again or choose an audio file.';$('voice-record').textContent='Record again'};recorder.start(250);$('voice-file').disabled=true;requesting=false;const started=Date.now();ticker=setInterval(()=>{$('voice-clock').textContent='0:'+String(Math.min(60,Math.floor((Date.now()-started)/1000))).padStart(2,'0')+' / 1:00'},250);$('voice-record').textContent='Stop recording';$('voice-status').textContent='Recording… microphone active. Stops automatically after 60 seconds.';$('voice-attach').disabled=true;timer=setTimeout(()=>{if(recorder?.state==='recording')recorder.stop()},60000)}catch(error){if(version===generation){stopTracks();$('voice-status').textContent=error.name==='NotAllowedError'?'Microphone permission was denied. Allow it in browser settings, or choose an audio file.':error.message}}finally{if(version===generation)requesting=false}};
function fileAudioType(file){const extension=file.name.split('.').pop().toLowerCase(),raw=String(file.type||'').split(';')[0].trim().toLowerCase(),aliases={'audio/x-m4a':'audio/mp4','audio/mp3':'audio/mpeg','audio/x-mp3':'audio/mpeg','audio/x-wav':'audio/wav','audio/wave':'audio/wav','audio/x-aac':'audio/aac'},types={'m4a':'audio/mp4','mp3':'audio/mpeg','wav':'audio/wav','ogg':'audio/ogg','webm':'audio/webm','aac':'audio/aac'},type=aliases[raw]||raw;if(Object.values(types).includes(type))return type;if(!raw||raw==='application/octet-stream'||raw==='video/mp4'&&extension==='m4a')return types[extension]||null;return null}
$('voice-file').onchange=()=>{if(recorder?.state==='recording'||uploading)return;const file=$('voice-file').files?.[0];$('voice-file').value='';if(file){const type=fileAudioType(file);if(!type){clipIssue('Choose M4A, MP3, WAV, OGG, WebM, or AAC audio (8 MB maximum).');return}if(!file.size||file.size>8000000){clipIssue('Clip is empty or exceeds 8 MB.');return}preview(new Blob([file],{type}))}};

$('voice-attach').onclick=async()=>{
 if(!blob||uploading)return;
 const version=generation,uploadGroup=group,clip=blob,controller=new AbortController();uploadController=controller;uploading=true;
 const deadline=setTimeout(()=>controller.abort(),90000);
 for(const id of ['voice-record','voice-file','voice-attach'])$(id).disabled=true;
 $('voice-status').textContent='Preparing voice clip…';
 try{
  const metadata=await clipMetadata(clip);if(version!==generation||!$('voice-dialog').open)return;$('voice-status').textContent='Uploading voice clip… Keep this dialog open to attach it.';
  const response=await fetch('/api/groupme/audio?group='+encodeURIComponent(uploadGroup),{method:'POST',credentials:'same-origin',headers:{'Content-Type':clip.type},body:clip,signal:controller.signal});
  let data;try{data=await response.json()}catch{throw Error('Dock sign-in expired or the upload response was unreadable. Sign in again, then retry this clip.')}
  if(version!==generation||!$('voice-dialog').open)return;
  if(!response.ok)throw Error(data.error||'Upload failed.');
  window.DockGroupMeAudioTarget.attach(uploadGroup,data.response.url,metadata);$('voice-dialog').close();
 }catch(error){if(version===generation)$('voice-status').textContent=['TypeError','TimeoutError','AbortError'].includes(error.name)?'The upload connection was interrupted. Your clip is kept here. Reconnect, then choose Attach clip again.':error.message}
 finally{clearTimeout(deadline);if(version===generation){uploading=false;uploadController=null;for(const id of ['voice-record','voice-file'])$(id).disabled=false;$('voice-attach').disabled=!blob}}
};
$('voice-close').onclick=()=>$('voice-dialog').close();$('voice-dialog').addEventListener('close',discard);window.addEventListener('pagehide',discard);

async function clipMetadata(clip){
 const AudioContext=window.AudioContext||window.webkitAudioContext;if(!AudioContext)throw Error('This browser cannot read the clip duration. Try a supported browser or another audio file.');
 const context=new AudioContext();try{const decoded=await context.decodeAudioData(await clip.arrayBuffer());if(!Number.isFinite(decoded.duration)||decoded.duration<=0||decoded.duration>3600)throw Error('Use an audio clip under one hour.');const samples=decoded.getChannelData(0),peaks=[];for(let i=0;i<64;i++){const start=Math.floor(i*samples.length/64),end=Math.floor((i+1)*samples.length/64);let max=0;for(let j=start,step=Math.max(1,Math.floor((end-start)/2048));j<end;j+=step)max=Math.max(max,Math.abs(samples[j]));peaks.push(Math.round(Math.min(1,max)*100)/100)}return {duration:Math.max(1,Math.ceil(decoded.duration)),peaks:JSON.stringify(peaks)}}catch(error){throw Error('Could not read the audio clip. Try recording again or choose a playable audio file.')}finally{await context.close().catch(()=>{})}
}
